using ghidra.program.util;

public class ListingHoverProvider : AbstractHoverProvider {

	public ListingHoverProvider() : base("ListingHoverProvider")
    {
	}

	public void addHoverService(ListingHoverService hoverService) {
		base.addHoverService(hoverService);
	}

	public void removeHoverService(ListingHoverService hoverService) {
		base.removeHoverService(hoverService);
	}

	/* @Override */
	public bool isForcePopups() {
		return true; // our enablement is controlled only by a user-level toolbar action
	}

	/* @Override */
	protected ProgramLocation getHoverLocation(FieldLocation fieldLocation, Field field,
			Rectangle fieldBounds, MouseEvent @event) {

		ProgramLocation loc = null;
		if (field is ListingField listingField) {
			loc = listingField.getFieldFactory()
					.getProgramLocation(fieldLocation.getRow(), fieldLocation.getCol(),
						listingField);
		}

		return loc;
	}

}
